// Which provider rows exist, and what the Agent's stored choices make of
// them: the part of AgentConfiguration.cpp that does not touch AppConfig.

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Agent/ProviderFactory.hpp"

#include <cstdlib>
#include <set>

using namespace Slic3r::GUI::JusPrin::Agent;

namespace {

class NullTransport final : public IAgentHttpTransport
{
public:
    bool post(AgentHttpRequest, EventFn) override { return true; }
    void cancel() override {}
};

std::unique_ptr<IAgentHttpTransport> null_transport() { return std::make_unique<NullTransport>(); }

AgentSettings configured(std::string provider, std::string key = "sk-stored")
{
    AgentSettings settings;
    settings.enabled       = true;
    settings.cloud_consent = true;
    settings.provider      = std::move(provider);
    settings.api_key       = std::move(key);
    return settings;
}

// Sets an environment variable for one scope and restores what was there.
class ScopedEnvironment
{
public:
    ScopedEnvironment(const char* name, const char* value) : m_name(name)
    {
        if (const char* old = std::getenv(name)) {
            m_had = true;
            m_old = old;
        }
        set(value);
    }
    ~ScopedEnvironment() { set(m_had ? m_old.c_str() : nullptr); }

private:
    void set(const char* value)
    {
#ifdef _WIN32
        _putenv_s(m_name, value == nullptr ? "" : value);
#else
        if (value == nullptr)
            unsetenv(m_name);
        else
            setenv(m_name, value, 1);
#endif
    }
    const char* m_name;
    bool        m_had{false};
    std::string m_old;
};

} // namespace

TEST_CASE("every provider row is complete and has an id of its own", "[agent][providers]")
{
    std::set<std::string> ids;
    for (const ProviderProfile& profile : provider_profiles()) {
        CAPTURE(profile.id);
        CHECK(ids.insert(profile.id).second);
        CHECK_FALSE(profile.endpoint.empty());
        CHECK_FALSE(profile.model.empty());
        CHECK_FALSE(profile.display_name.empty());
        CHECK(profile_for(profile.id) == &profile);
    }
    CHECK(ids == std::set<std::string>{"openai", "openrouter"});
    CHECK(profile_for("anthropic") == nullptr);
    CHECK(&openai_profile() == profile_for("openai"));
}

TEST_CASE("a stored OpenRouter choice loads a ready OpenRouter agent", "[agent][providers][openrouter]")
{
    const AgentRuntime runtime = resolve_agent_runtime(configured("openrouter"), "", &null_transport);
    CHECK(runtime.provider == "openrouter");
    CHECK(runtime.availability == AgentAvailability::Ready);
    REQUIRE(runtime.service != nullptr);
    CHECK(runtime.service->ready());
    CHECK(runtime.unavailable_reason.empty());
}

TEST_CASE("the stored choices say why there is no agent, in the provider's own name", "[agent][providers]")
{
    SECTION("no provider stored means OpenAI, as before")
    {
        const AgentRuntime runtime = resolve_agent_runtime(configured(""), "", &null_transport);
        CHECK(runtime.provider == "openai");
        CHECK(runtime.availability == AgentAvailability::Ready);
    }
    SECTION("an OpenRouter choice without its key")
    {
        const AgentRuntime runtime = resolve_agent_runtime(configured("openrouter", ""), "", &null_transport);
        CHECK(runtime.service == nullptr);
        CHECK(runtime.unavailable_reason == "No OpenRouter API key is configured.");
    }
    SECTION("an OpenAI choice without its key")
    {
        const AgentRuntime runtime = resolve_agent_runtime(configured("openai", ""), "", &null_transport);
        CHECK(runtime.unavailable_reason == "No OpenAI API key is configured.");
    }
    SECTION("a provider this build has no row for")
    {
        const AgentRuntime runtime = resolve_agent_runtime(configured("anthropic"), "", &null_transport);
        CHECK(runtime.service == nullptr);
        CHECK(runtime.unavailable_reason == "The configured Agent provider is not supported.");
    }
    SECTION("not enabled, or no consent")
    {
        AgentSettings settings = configured("openrouter");
        settings.cloud_consent = false;
        CHECK(resolve_agent_runtime(settings, "", &null_transport).unavailable_reason ==
              "Cloud Agent access requires explicit consent.");
        settings.enabled = false;
        CHECK(resolve_agent_runtime(settings, "", &null_transport).unavailable_reason == "The Agent is not enabled.");
    }
}

TEST_CASE("JUSPRIN_AGENT_ENDPOINT redirects the Agent, and JUSPRIN_OPENAI_ENDPOINT still does", "[agent][providers]")
{
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", nullptr);
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", nullptr);
        CHECK(agent_endpoint_override().empty());
    }
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", nullptr);
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", "http://127.0.0.1:1/v1/responses");
        CHECK(agent_endpoint_override() == "http://127.0.0.1:1/v1/responses");
    }
    {
        ScopedEnvironment agent("JUSPRIN_AGENT_ENDPOINT", "http://127.0.0.1:2/v1/responses");
        ScopedEnvironment openai("JUSPRIN_OPENAI_ENDPOINT", "http://127.0.0.1:1/v1/responses");
        CHECK(agent_endpoint_override() == "http://127.0.0.1:2/v1/responses");
    }

    // The override reaches the agent of whichever provider is stored.
    struct Capture final : IAgentHttpTransport
    {
        explicit Capture(std::string& url) : url(url) {}
        bool post(AgentHttpRequest request, EventFn) override
        {
            url = request.url;
            return true;
        }
        void cancel() override {}
        std::string& url;
    };
    std::string  url;
    AgentRuntime runtime = resolve_agent_runtime(configured("openrouter"), "http://127.0.0.1:3/v1/responses",
                                                 [&url]() -> std::unique_ptr<IAgentHttpTransport> { return std::make_unique<Capture>(url); });
    AgentRequest request;
    request.request_id = "r";
    request.user_text  = "hi";
    REQUIRE(runtime.service->start(request));
    CHECK(url == "http://127.0.0.1:3/v1/responses");
}

// Live smoke for the OpenRouter provider: real requests through the app's
// own HTTP transport, the agent the app builds, and the project chat's tools.
//
// Every case here spends money, so every case is hidden: nothing runs unless
// it is asked for by tag, and a case without OPENROUTER_API_KEY skips. Run it
// only for a batch Kenneth has approved:
//
//   ( . "$HOME/.config/jusprin/prompt-test.env"; agent_live_tests "[live]" )
//
// It answers what the design left unverified about OpenRouter's Responses
// endpoint: whether it honours `instructions`, accepts `strict` and
// `parallel_tool_calls`, replays a turn's own output on a continuation, takes
// an image the way the app sends it (a user message after the results), and
// takes an image inside a function_call_output, which the app does not send
// today but another codec might.

#include <catch2/catch_all.hpp>

#include "slic3r/GUI/JusPrin/Agent/OpenAIResponsesAgent.hpp"
#include "slic3r/GUI/JusPrin/Agent/ProviderFactory.hpp"

#include <nlohmann/json.hpp>

#include <chrono>
#include <condition_variable>
#include <cstdlib>
#include <mutex>
#include <thread>

using namespace Slic3r::GUI::JusPrin::Agent;
using nlohmann::json;

namespace {

// A 1x1 PNG.
constexpr const char* kPixel = "iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mP8z8BQDwAEhQGAhKmMIQAAAABJRU5ErkJggg==";

std::string openrouter_key()
{
    const char* key = std::getenv("OPENROUTER_API_KEY");
    return key == nullptr ? std::string() : std::string(key);
}

// The real transport, with every request it posts kept for the test to read.
class RecordingTransport final : public IAgentHttpTransport
{
public:
    explicit RecordingTransport(std::vector<AgentHttpRequest>& sent) : m_sent(sent) {}
    bool post(AgentHttpRequest request, EventFn event) override
    {
        m_sent.push_back(request);
        return m_inner->post(std::move(request), std::move(event));
    }
    void cancel() override { m_inner->cancel(); }

private:
    std::vector<AgentHttpRequest>&       m_sent;
    std::unique_ptr<IAgentHttpTransport> m_inner{make_openai_http_transport()};
};

struct Turn
{
    std::string                  text;
    std::optional<AgentToolCall> call;
    std::optional<AgentError>    error;
    bool                         completed{false};
};

// Polls until the turn completes, fails or asks for a tool, as the GUI tick would.
Turn run_until_settled(IAgentService& agent)
{
    Turn       turn;
    const auto deadline = std::chrono::steady_clock::now() + std::chrono::seconds(180);
    while (std::chrono::steady_clock::now() < deadline) {
        while (std::optional<AgentEvent> event = agent.poll()) {
            switch (event->kind) {
            case AgentEventKind::TextDelta: turn.text += event->text; break;
            case AgentEventKind::ToolCall: turn.call = event->tool; return turn;
            case AgentEventKind::Completed: turn.completed = true; return turn;
            case AgentEventKind::Failed: turn.error = event->error; return turn;
            }
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(50));
    }
    FAIL("no answer from OpenRouter within 180 s");
    return turn;
}

AgentServicePtr live_agent(std::vector<AgentHttpRequest>& sent, std::vector<AgentUsage>& usage)
{
    ProviderListeners listeners;
    listeners.usage = [&usage](const AgentUsage& reported) { usage.push_back(reported); };
    return make_provider_agent(*profile_for("openrouter"), openrouter_key(), "", "", std::make_unique<RecordingTransport>(sent),
                               std::move(listeners));
}

void report(const std::vector<AgentUsage>& usage)
{
    for (const AgentUsage& one : usage)
        WARN("usage: input " << one.input << " (cached " << one.cached_input << "), output " << one.output);
}

} // namespace

TEST_CASE("OpenRouter honours the instructions with the project tools offered, strict and parallel calls on",
          "[agent][openrouter][live][.]")
{
    if (openrouter_key().empty())
        SKIP("OPENROUTER_API_KEY is not set");
    std::vector<AgentHttpRequest> sent;
    std::vector<AgentUsage>       usage;
    AgentServicePtr               agent = live_agent(sent, usage);

    AgentRequest request;
    request.request_id                = "live-instructions";
    request.session.instructions      = "You are a connectivity check. Whatever the user writes, reply with exactly the word "
                                        "PINEAPPLE and nothing else. Do not call any tool.";
    request.session.include_workspace = false;
    request.user_text                 = "Hello, are you there?";
    REQUIRE(agent->start(request));
    const Turn turn = run_until_settled(*agent);
    report(usage);

    INFO("reply: " << turn.text << (turn.error ? " error: " + turn.error->code + " " + turn.error->message : ""));
    // Accepted at all: the body carried strict tools and parallel_tool_calls.
    REQUIRE_FALSE(turn.error);
    REQUIRE(turn.completed);
    const json body = json::parse(sent.front().body);
    CHECK(body["parallel_tool_calls"] == true);
    CHECK(std::any_of(body["tools"].begin(), body["tools"].end(), [](const json& tool) { return tool["strict"] == true; }));
    CHECK(body["tools"].size() == 28);
    // Honoured: the instructions, not the person, decided the words.
    CHECK(turn.text.find("PINEAPPLE") != std::string::npos);
    CHECK(usage.size() == 1);
}

TEST_CASE("OpenRouter makes a tool call and continues from its result and the image after it", "[agent][openrouter][live][.]")
{
    if (openrouter_key().empty())
        SKIP("OPENROUTER_API_KEY is not set");
    std::vector<AgentHttpRequest> sent;
    std::vector<AgentUsage>       usage;
    AgentServicePtr               agent = live_agent(sent, usage);

    AgentRequest request;
    request.request_id                = "live-tool-call";
    request.session.instructions      = "You are a connectivity check. First call the workspace_inspect tool once, with sections "
                                        "[\"summary\"]. When its result arrives, reply with one short sentence saying you received it "
                                        "and whether an image came with it.";
    request.session.include_workspace = false;
    request.user_text                 = "Run the check.";
    REQUIRE(agent->start(request));
    const Turn first = run_until_settled(*agent);
    INFO("first reply: " << first.text << (first.error ? " error: " + first.error->code : ""));
    REQUIRE_FALSE(first.error);
    REQUIRE(first.call);
    CHECK(first.call->request.tool == "workspace_inspect");

    // The app's way of sending a picture: the result as text, the image in a
    // user message after it. The continuation also replays the response's own
    // output items, reasoning included.
    AgentToolResult result{first.call->call_id, "succeeded", R"({"state":"succeeded","result":{"summary":{"objects":1}}})"};
    result.image = std::make_shared<ToolImage>(ToolImage{"image/png", kPixel, 1, 1});
    REQUIRE(agent->continue_after_tool(result));
    const Turn second = run_until_settled(*agent);
    report(usage);
    INFO("second reply: " << second.text << (second.error ? " error: " + second.error->code + " " + second.error->message : ""));
    REQUIRE_FALSE(second.error);
    CHECK(second.completed);
    CHECK_FALSE(second.text.empty());
    REQUIRE(sent.size() == 2);
    CHECK(sent.back().body.find("input_image") != std::string::npos);
}

// Not what the app sends today: a probe for a later codec. A failure here is
// the answer "OpenRouter does not take an image inside a function result".
TEST_CASE("OpenRouter takes an image inside a function_call_output", "[agent][openrouter][live][.]")
{
    if (openrouter_key().empty())
        SKIP("OPENROUTER_API_KEY is not set");
    const ProviderProfile& profile = *profile_for("openrouter");
    const json tool{{"type", "function"},
                    {"name", "look"},
                    {"description", "Look at the picture."},
                    {"strict", true},
                    {"parameters", json{{"type", "object"}, {"properties", json::object()}, {"required", json::array()},
                                        {"additionalProperties", false}}}};
    const json input = json::array(
        {json{{"role", "user"}, {"content", "Look at the picture and say in one word what you see."}},
         json{{"type", "function_call"}, {"call_id", "call_probe"}, {"name", "look"}, {"arguments", "{}"}},
         json{{"type", "function_call_output"},
              {"call_id", "call_probe"},
              {"output", json::array({json{{"type", "input_text"}, {"text", "The picture:"}},
                                      json{{"type", "input_image"}, {"image_url", std::string("data:image/png;base64,") + kPixel}}})}}});
    AgentHttpRequest request;
    request.url     = profile.endpoint;
    request.headers = {{"Authorization", "Bearer " + openrouter_key()}};
    request.headers.insert(request.headers.end(), profile.headers.begin(), profile.headers.end());
    request.body = json{{"model", profile.model}, {"store", false}, {"stream", true}, {"tools", json::array({tool})},
                        {"input", input}}
                       .dump();

    std::mutex              mutex;
    std::condition_variable done;
    std::string             stream;
    std::string             error;
    unsigned                status{0};
    bool                    finished{false};
    std::unique_ptr<IAgentHttpTransport> transport = make_openai_http_transport();
    REQUIRE(transport->post(std::move(request), [&](AgentHttpEvent event) {
        std::lock_guard<std::mutex> lock(mutex);
        if (event.kind == AgentHttpEvent::Kind::Data) {
            stream += event.data;
            return;
        }
        status   = event.status;
        error    = event.error;
        finished = true;
        done.notify_all();
    }));
    {
        std::unique_lock<std::mutex> lock(mutex);
        REQUIRE(done.wait_for(lock, std::chrono::seconds(180), [&finished] { return finished; }));
    }
    INFO("status " << status << " " << error << "\n" << stream.substr(0, 2000));
    CHECK(status == 200);
    CHECK(stream.find("response.completed") != std::string::npos);
}

