// Reads the terminal event of one streamed response and logs what it cost:
// usage.cost when OpenRouter reports it, otherwise the listed price times
// the reported tokens, marked as computed.
void meter(int number, const std::string& stream, unsigned status, const std::string& error)
{
    json        terminal;
    std::size_t at = 0;
    while ((at = stream.find("data:", at)) != std::string::npos) {
        at += 5;
        const std::size_t end = stream.find('\\n', at);
        const json        event = json::parse(stream.substr(at, end == std::string::npos ? std::string::npos : end - at), nullptr, false);
        if (event.is_object() && event.contains("response") &&
            (event.value("type", "") == "response.completed" || event.value("type", "") == "response.failed" ||
             event.value("type", "") == "response.incomplete"))
            terminal = event;
        else if (event.is_object() && event.value("type", "") == "error")
            terminal = event;
    }
    const json  response = terminal.contains("response") ? terminal["response"] : json::object();
    const json  usage    = response.value("usage", json::object());
    double      cost     = 0;
    std::string how      = "none reported";
    if (usage.contains("cost") && usage["cost"].is_number()) {
        cost = usage["cost"].get<double>();
        how  = "usage.cost";
    } else if (usage.contains("input_tokens")) {
        cost = usage.value("input_tokens", 0.0) * kInputPricePerTok + usage.value("output_tokens", 0.0) * kOutputPricePerTok;
        how  = "computed from tokens";
    }
    double total;
    {
        std::lock_guard<std::mutex> lock(g_spend_mutex);
        g_spent += cost;
        total = g_spent;
    }
