              << " input_tokens=" << usage.value("input_tokens", 0) << " output_tokens=" << usage.value("output_tokens", 0)
              << " cost=$" << cost << " (" << how << ") running_total=$" << total << '\\n';
    if (terminal.value("type", "") != "response.completed")
        std::cerr << "LIVE REQUEST " << number << " stream: " << stream.substr(0, 1500) << '\\n';
}

// Sends one request through the app's real transport unless it could take
// the spend past the cap, logs what went out, and meters what came back.
bool metered_post(IAgentHttpTransport& transport, AgentHttpRequest request, IAgentHttpTransport::EventFn event)
{
    int number;
    {
        std::lock_guard<std::mutex> lock(g_spend_mutex);
        if (g_spent + kWorstRequestCost > kSpendCap) {
            std::cerr << "LIVE REQUEST refused: $" << g_spent << " spent, cap $" << kSpendCap << '\\n';
            return false;
        }
        number = ++g_requests;
    }
    const json body = json::parse(request.body);
    std::cerr << "LIVE REQUEST " << number << " sent " << request.body.size() << " bytes to " << request.url
              << " model=" << body.value("model", "") << " tools=" << body.value("tools", json::array()).size()
              << " input_items=" << body.value("input", json::array()).size()
              << " parallel_tool_calls=" << body.value("parallel_tool_calls", json()).dump() << '\\n';
    auto stream = std::make_shared<std::string>();
    return transport.post(std::move(request), [number, stream, event = std::move(event)](AgentHttpEvent http) {
        if (http.kind == AgentHttpEvent::Kind::Data)
            *stream += http.data;
        else
            meter(number, *stream, http.status, http.error);
        event(std::move(http));
    });
}

